def list_icons(status=None, category=None, style=None, version_introduced=None, cursor=None, limit=None, sort=None, order=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0492000" if __import__("os").path.isdir("./environment_mix/0492000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _as_dt(v):
        if isinstance(v, str) and v:
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _log(status_code, used_credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        row = {
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": "list_icons",
            "credential_id": used_credential_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Basic ambient auth: if store has credentials/workspaces, require at least one usable combo; otherwise allow.
    def _authorize_or_none():
        creds = _load("credentials.json")
        workspaces = _load("workspaces.json")
        subs = _load("subscriptions.json")
        # If none exist, treat as public surface.
        if not isinstance(creds, list) and not isinstance(workspaces, list) and not isinstance(subs, list):
            return None
        if isinstance(creds, list) and creds:
            # choose any non-revoked/active if field exists
            for c in creds:
                if not isinstance(c, dict): 
                    continue
                if c.get("status") in (None, "active", "enabled"):
                    return c.get("id")
            return creds[0].get("id") if isinstance(creds[0], dict) else None
        # fallback: any workspace indicates accessible
        if isinstance(workspaces, list) and workspaces:
            ws = workspaces[0]
            if isinstance(ws, dict):
                return ws.get("id")
            return None
        return None

    cred_id = _authorize_or_none()

    # Rate limiting / quota if store declares it
    def _enforce_limits():
        limits = _load("rate_limits.json")
        quotas = _load("quotas.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()

        # Rate limit: any rule with window_seconds and max_requests
        if isinstance(limits, list):
            for rule in limits:
                if not isinstance(rule, dict):
                    continue
                window = rule.get("window_seconds")
                maxr = rule.get("max_requests")
                scope = rule.get("scope", "global")
                if not isinstance(window, int) or not isinstance(maxr, int) or window <= 0 or maxr < 0:
                    continue
                cutoff = now - datetime.timedelta(seconds=window)
                cnt = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    ts = _as_dt(r.get("timestamp"))
                    if not ts or ts < cutoff:
                        continue
                    if scope == "credential" and cred_id and r.get("credential_id") != cred_id:
                        continue
                    if scope == "endpoint" and r.get("endpoint") != "list_icons":
                        continue
                    if scope == "credential+endpoint":
                        if cred_id and r.get("credential_id") != cred_id:
                            continue
                        if r.get("endpoint") != "list_icons":
                            continue
                    cnt += 1
                if cnt >= maxr:
                    return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window, max_requests=maxr)
        # Quota: any rule with period and max_requests (daily/monthly)
        if isinstance(quotas, list):
            for rule in quotas:
                if not isinstance(rule, dict):
                    continue
                period = rule.get("period")  # "day" or "month"
                maxr = rule.get("max_requests")
                scope = rule.get("scope", "global")
                if period not in ("day", "month") or not isinstance(maxr, int) or maxr < 0:
                    continue
                if period == "day":
                    cutoff = now - datetime.timedelta(days=1)
                else:
                    cutoff = now - datetime.timedelta(days=31)
                cnt = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    ts = _as_dt(r.get("timestamp"))
                    if not ts or ts < cutoff:
                        continue
                    if scope == "credential" and cred_id and r.get("credential_id") != cred_id:
                        continue
                    cnt += 1
                if cnt >= maxr:
                    return _err("QUOTA_EXCEEDED", "Quota exceeded", period=period, max_requests=maxr)
        return None

    limerr = _enforce_limits()
    if limerr:
        _log("QUOTA_EXCEEDED" if limerr["error"]["code"] == "QUOTA_EXCEEDED" else "RATE_LIMIT", cred_id)
        return limerr

    # Validate inputs
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deprecated", "hidden"):
            _log("VALIDATION_ERROR", cred_id)
            return _err("VALIDATION_ERROR", "Invalid status. Must be one of: active, deprecated, hidden.")
    if category is not None and not isinstance(category, str):
        _log("VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "Invalid category. Must be a string.")
    if style is not None and not isinstance(style, str):
        _log("VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "Invalid style. Must be a string.")
    if version_introduced is not None and not isinstance(version_introduced, str):
        _log("VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "Invalid version_introduced. Must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "Invalid limit. Must be an integer between 1 and 200.")
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "display_name", "slug"):
        _log("VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "Invalid sort. Must be one of: created_at, updated_at, display_name, slug.")
    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "Invalid order. Must be one of: asc, desc.")

    # Cursor format: "<sort_value>|<id>" (sort_value urlsafe-ish), or empty/None
    cursor_sort_val = None
    cursor_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or "|" not in cursor:
            _log("VALIDATION_ERROR", cred_id)
            return _err("VALIDATION_ERROR", "Malformed cursor.")
        parts = cursor.split("|", 1)
        if len(parts) != 2 or not parts[1]:
            _log("VALIDATION_ERROR", cred_id)
            return _err("VALIDATION_ERROR", "Malformed cursor.")
        cursor_sort_val, cursor_id = parts[0], parts[1]

    icons = _load("icons.json")
    if not isinstance(icons, list):
        icons = []

    # Business rule: exclude hidden unless internal/admin flag exists (not exposed) => always exclude hidden
    allowed_statuses = ("active", "deprecated")
    if status is not None:
        if status == "hidden":
            # tool surface cannot list hidden
            _log("VALIDATION_ERROR", cred_id)
            return _err("VALIDATION_ERROR", "status=hidden is not allowed on this surface.")
        wanted_statuses = (status,)
    else:
        wanted_statuses = allowed_statuses

    filtered = []
    for ic in icons:
        if not isinstance(ic, dict):
            continue
        if ic.get("status") not in wanted_statuses:
            continue
        if category is not None and ic.get("category") != category:
            continue
        if style is not None and ic.get("style") != style:
            continue
        if version_introduced is not None and ic.get("version_introduced") != version_introduced:
            continue
        filtered.append(ic)

    def _sort_key(row):
        v = row.get(sort)
        if sort in ("created_at", "updated_at"):
            dt = _as_dt(v)
            return (dt or datetime.datetime.min, row.get("id") or "")
        if v is None:
            v = ""
        return (str(v).lower(), row.get("id") or "")

    reverse = (order == "desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    # Apply cursor
    if cursor is not None:
        def _row_cursor_tuple(row):
            v = row.get(sort)
            if sort in ("created_at", "updated_at"):
                dt = _as_dt(v)
                sv = (dt.isoformat() + "Z") if dt else ""
            else:
                sv = "" if v is None else str(v)
            return (sv, row.get("id") or "")
        # Find first row after cursor based on current sort/order
        start_idx = 0
        found = False
        for i, row in enumerate(filtered):
            sv, rid = _row_cursor_tuple(row)
            if reverse:
                if (sv, rid) < (cursor_sort_val, cursor_id):
                    start_idx = i
                    found = True
                    break
            else:
                if (sv, rid) > (cursor_sort_val, cursor_id):
                    start_idx = i
                    found = True
                    break
        if not found:
            start_idx = len(filtered)
        page = filtered[start_idx:start_idx + limit]
    else:
        page = filtered[:limit]

    has_more = len(page) == limit and (len(filtered) > (filtered.index(page[-1]) + 1) if page else False)
    next_cursor = None
    if page and (filtered.index(page[-1]) < len(filtered) - 1):
        last = page[-1]
        v = last.get(sort)
        if sort in ("created_at", "updated_at"):
            dt = _as_dt(v)
            sv = (dt.isoformat() + "Z") if dt else ""
        else:
            sv = "" if v is None else str(v)
        next_cursor = f"{sv}|{last.get('id','')}"
        has_more = True
    else:
        has_more = False

    out = {
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "sort": sort,
            "order": order,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _log("OK", cred_id, meta={"returned": len(page), "total": len(filtered)})
    return out

def search_icons(query, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0492000" if __import__("os").path.isdir("./environment_mix/0492000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _lat_ms():
        return int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)

    def _parse_iso(ts):
        if not isinstance(ts, str) or not ts:
            return None
        s = ts.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s.replace("+00:00", ""))
        except ValueError:
            return None

    def _log(status_code, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": "search_icons",
                "credential_id": None,
                "status": status_code,
                "latency_ms": _lat_ms(),
                "timestamp": _now_iso(),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            # Logging must never break the API call
            pass

    def _rate_limit_or_none():
        # Best-effort: if request_logs.json exists, enforce conservative limits.
        # (Vendor limits unknown; use sensible defaults and only enforce when log file is present.)
        try:
            path = os.path.join(_DB, "request_logs.json")
            if not os.path.exists(path):
                return None
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return None
            now = datetime.datetime.utcnow()
            window = now - datetime.timedelta(seconds=60)
            day = now.replace(hour=0, minute=0, second=0, microsecond=0)

            per_min = 0
            per_day = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                ts = _parse_iso(r.get("timestamp") or r.get("created_at"))
                if ts is None:
                    continue
                if ts >= window:
                    per_min += 1
                if ts >= day:
                    per_day += 1

            # Defaults: permissive but real.
            if per_min >= 120:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
            if per_day >= 10000:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
            return None
        except Exception:
            return None

    # ---- validate input (business rules) ----
    if not isinstance(query, str):
        err = _err("VALIDATION_ERROR", "query must be a string.", field="query")
        _log("VALIDATION_ERROR", {"error": err["error"]})
        return err

    q = query.strip()
    if not q:
        err = _err("VALIDATION_ERROR", "query must be a non-empty string after trimming.", field="query")
        _log("VALIDATION_ERROR", {"error": err["error"]})
        return err

    parts = [p.strip() for p in q.split(",")]
    parts = [p for p in parts if p]  # drop empty subqueries
    if not parts:
        err = _err("VALIDATION_ERROR", "query must contain at least one non-empty search term.", field="query")
        _log("VALIDATION_ERROR", {"error": err["error"]})
        return err
    if len(parts) > 20:
        err = _err("VALIDATION_ERROR", "query may contain at most 20 comma-separated terms.", field="query")
        _log("VALIDATION_ERROR", {"error": err["error"]})
        return err
    for p in parts:
        if len(p) < 1 or len(p) > 128:
            err = _err("VALIDATION_ERROR", "Each search term must be 1..128 characters after trimming.", field="query", term=p)
            _log("VALIDATION_ERROR", {"error": err["error"]})
            return err

    rl = _rate_limit_or_none()
    if rl:
        _log(rl["error"]["code"], {"error": rl["error"]})
        return rl

    # ---- load data ----
    icons = _load("icons.json")
    tags = _load("tags.json")
    icon_tags = _load("icon_tags.json")
    aliases = _load("icon_aliases.json")

    if not isinstance(icons, list):
        icons = []
    if not isinstance(tags, list):
        tags = []
    if not isinstance(icon_tags, list):
        icon_tags = []
    if not isinstance(aliases, list):
        aliases = []

    # Only exposed statuses
    visible_status = {"active", "deprecated"}

    icon_by_id = {r.get("id"): r for r in icons if isinstance(r, dict) and isinstance(r.get("id"), str)}
    visible_icon_ids = {i for i, r in icon_by_id.items() if isinstance(r, dict) and r.get("status") in visible_status}

    tag_by_id = {t.get("id"): t for t in tags if isinstance(t, dict) and isinstance(t.get("id"), str)}

    # Pre-index joins
    icon_ids_by_tag_id = {}
    for j in icon_tags:
        if not isinstance(j, dict):
            continue
        iid = j.get("icon_id")
        tid = j.get("tag_id")
        if not isinstance(iid, str) or not isinstance(tid, str):
            continue
        icon_ids_by_tag_id.setdefault(tid, set()).add(iid)

    # Active aliases -> icon_id
    icon_ids_by_alias = []
    for a in aliases:
        if not isinstance(a, dict):
            continue
        if a.get("status") != "active":
            continue
        alias_txt = a.get("alias")
        iid = a.get("icon_id")
        if isinstance(alias_txt, str) and isinstance(iid, str):
            icon_ids_by_alias.append((alias_txt, iid))

    def _ilike(haystack, needle):
        # Case-insensitive substring match similar to ILIKE %needle%
        if not isinstance(haystack, str) or not isinstance(needle, str):
            return False
        return needle.lower() in haystack.lower()

    def _tokenize(s):
        # Used for keyword containment; normalize to simple tokens
        if not isinstance(s, str):
            return []
        return [t for t in re.split(r"[\s\-_]+", s.strip().lower()) if t]

    matched_ids = set()
    match_reasons = {}  # icon_id -> list of reasons

    for term in parts:
        term_l = term.lower()

        # (a) icons.slug/display_name ILIKE
        for iid in visible_icon_ids:
            icon = icon_by_id.get(iid)
            if not isinstance(icon, dict):
                continue
            if _ilike(icon.get("slug", ""), term) or _ilike(icon.get("display_name", ""), term):
                matched_ids.add(iid)
                match_reasons.setdefault(iid, []).append({"term": term, "via": "icon_fields"})

        # (b) aliases.alias ILIKE with active alias
        for alias_txt, iid in icon_ids_by_alias:
            if iid in visible_icon_ids and _ilike(alias_txt, term):
                matched_ids.add(iid)
                match_reasons.setdefault(iid, []).append({"term": term, "via": "alias"})

        # (c) tags.name ILIKE joined via icon_tags
        for tid, trow in tag_by_id.items():
            if not isinstance(trow, dict):
                continue
            if _ilike(trow.get("name", ""), term):
                for iid in icon_ids_by_tag_id.get(tid, set()):
                    if iid in visible_icon_ids:
                        matched_ids.add(iid)
                        match_reasons.setdefault(iid, []).append({"term": term, "via": "tag", "tag_id": tid})

        # (d) icons.keywords contains token
        tokens = _tokenize(term)
        if tokens:
            tokset = set(tokens)
            for iid in visible_icon_ids:
                icon = icon_by_id.get(iid)
                kws = icon.get("keywords") if isinstance(icon, dict) else None
                if not isinstance(kws, list):
                    continue
                # keywords are already normalized; do contains on lower
                kwset = set()
                ok = True
                for k in kws:
                    if not isinstance(k, str):
                        ok = False
                        break
                    kwset.add(k.lower())
                if not ok:
                    continue
                if tokset & kwset:
                    matched_ids.add(iid)
                    match_reasons.setdefault(iid, []).append({"term": term, "via": "keywords"})

    # Build results (deduped by icon_id)
    rows = [icon_by_id[iid] for iid in matched_ids if iid in icon_by_id and icon_by_id[iid].get("status") in visible_status]

    # Stable-ish ordering: exact-ish matches first by simple score, then slug.
    def _score(icon):
        iid = icon.get("id")
        reasons = match_reasons.get(iid, [])
        # more reasons = higher, direct field hits count more
        s = 0
        for r in reasons:
            via = r.get("via")
            if via == "icon_fields":
                s += 3
            elif via == "alias":
                s += 2
            elif via == "tag":
                s += 1
            elif via == "keywords":
                s += 1
        return s

    rows.sort(key=lambda r: (-_score(r), (r.get("slug") or ""), (r.get("id") or "")))

    resp = {
        "data": rows,
        "meta": {
            "query": query,
            "terms": parts,
            "total": len(rows)
        }
    }
    _log("OK", {"total": len(rows)})
    return resp

def get_platform_usage(platform, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0492000" if __import__("os").path.isdir("./environment_mix/0492000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _lat_ms():
        return int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)

    def _parse_iso(ts):
        if not isinstance(ts, str) or not ts:
            return None
        s = ts.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s.replace("+00:00", ""))
        except ValueError:
            return None

    def _log(status_code, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": "get_platform_usage",
                "credential_id": None,
                "status": status_code,
                "latency_ms": _lat_ms(),
                "timestamp": _now_iso(),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _rate_limit_or_none():
        try:
            path = os.path.join(_DB, "request_logs.json")
            if not os.path.exists(path):
                return None
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return None
            now = datetime.datetime.utcnow()
            window = now - datetime.timedelta(seconds=60)
            day = now.replace(hour=0, minute=0, second=0, microsecond=0)

            per_min = 0
            per_day = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                ts = _parse_iso(r.get("timestamp") or r.get("created_at"))
                if ts is None:
                    continue
                if ts >= window:
                    per_min += 1
                if ts >= day:
                    per_day += 1

            if per_min >= 120:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
            if per_day >= 10000:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
            return None
        except Exception:
            return None

    supported = {"react", "vue", "angular", "svelte", "react-native", "flutter"}
    if not isinstance(platform, str):
        err = _err("VALIDATION_ERROR", "platform must be a string.", field="platform")
        _log("VALIDATION_ERROR", {"error": err["error"]})
        return err
    if platform not in supported:
        err = _err("VALIDATION_ERROR", "Unsupported platform.", field="platform", supported=sorted(supported))
        _log("VALIDATION_ERROR", {"error": err["error"]})
        return err

    rl = _rate_limit_or_none()
    if rl:
        _log(rl["error"]["code"], {"error": rl["error"]})
        return rl

    guides = _load("platform_guides.json")
    if not isinstance(guides, list):
        guides = []

    matches = [g for g in guides if isinstance(g, dict) and g.get("platform") == platform and g.get("status") == "active"]
    if len(matches) != 1:
        # business rule: must return exactly one active row
        if len(matches) == 0:
            err = _err("NOT_FOUND", "No active platform usage guide found for the specified platform.", platform=platform)
            _log("NOT_FOUND", {"error": err["error"]})
            return err
        err = _err("CONFLICT", "Multiple active platform usage guides exist for the specified platform.", platform=platform, count=len(matches))
        _log("CONFLICT", {"error": err["error"]})
        return err

    resp = {"data": matches[0]}
    _log("OK", {"platform": platform})
    return resp

def get_icon(id, **_extra):
    import json, os, datetime
