        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=60, limit_per_minute=120)
        if per_day >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit_per_day=20000)
        return None

    # Validate inputs
    if not isinstance(id, str) or not id:
        e = _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
        _log("VALIDATION_ERROR", {"error": e["error"]})
        return e
    if status not in ("active", "disabled"):
        e = _err("VALIDATION_ERROR", "Unsupported status.", field="status", allowed=["active", "disabled"])
        _log("VALIDATION_ERROR", {"error": e["error"]})
        return e

    rl = _rate_limit_check()
    if rl is not None:
        _log("RATE_LIMIT", {"error": rl["error"]})
        return rl

    aliases = _load("icon_aliases.json")
    if not isinstance(aliases, list):
        aliases = []

    # Accept either alias primary key OR (common caller mistake) an icon_id; if icon_id is provided, update all its aliases.
    matched_idx = [i for i, r in enumerate(aliases) if isinstance(r, dict) and r.get("id") == id]
    by_icon_idx = []
    if not matched_idx:
        by_icon_idx = [i for i, r in enumerate(aliases) if isinstance(r, dict) and r.get("icon_id") == id]

    if not matched_idx and not by_icon_idx:
        e = _err("NOT_FOUND", "Icon alias not found.", id=id)
        _log("NOT_FOUND", {"error": e["error"]})
        return e

    now = _now_iso()

    # Lifecycle transitions
    allowed = {"active": ["disabled"], "disabled": ["active"]}
    updated_rows = []

    def _apply(i):
        r = aliases[i]
        cur = r.get("status")
        if cur == status:
            # Idempotent: update updated_at and return row as-is
            r["updated_at"] = now
            aliases[i] = r
            updated_rows.append(r)
            return None
        if cur not in allowed or status not in allowed[cur]:
            return _err("INVALID_TRANSITION", "Status transition is not allowed by lifecycle rules.", id=r.get("id"), from_status=cur, to_status=status)
        r["status"] = status
        r["updated_at"] = now
        aliases[i] = r
        updated_rows.append(r)
        return None

    # Update
    if matched_idx:
        err = _apply(matched_idx[0])
        if err is not None:
            _log("INVALID_TRANSITION", {"error": err["error"]})
            return err
    else:
        # Update all aliases for that icon_id
        for i in by_icon_idx:
            err = _apply(i)
            if err is not None:
                _log("INVALID_TRANSITION", {"error": err["error"]})
                return err

    _save("icon_aliases.json", aliases)

    # Return: if multiple updated, return them as a list (more informative than claiming one row)
    resp = {"data": updated_rows[0] if len(updated_rows) == 1 else updated_rows}
    _log("OK", {"updated": len(updated_rows), "target": id, "new_status": status})
    return resp
